export function toPythonRepresentation(value) {
  if (isPyBytes(value)) {
    return bytesRepresentation(value.raw);
  }

  if (Array.isArray(value)) {
    return `[${value.map(toPythonRepresentation).join(", ")}]`;
  }

  if (typeof value === "bigint") {
    return value.toString();
  }

  if (typeof value === "number") {
    return String(value);
  }

  return String(value);
}

function bytesRepresentation(raw) {
  const quote = selectQuote(raw);
  let body = "";

  for (let index = 0; index < raw.length; index += 1) {
    const byte = raw.charCodeAt(index);

    if (byte === 0x5c) {
      body += "\\\\";
      continue;
    }

    if (quote === "'" && byte === 0x27) {
      body += "\\'";
      continue;
    }

    if (quote === '"' && byte === 0x22) {
      body += '\\"';
      continue;
    }

    if (byte === 0x09) {
      body += "\\t";
      continue;
    }

    if (byte === 0x0a) {
      body += "\\n";
      continue;
    }

    if (byte === 0x0d) {
      body += "\\r";
      continue;
    }

    if (byte >= 0x20 && byte <= 0x7e) {
      body += String.fromCharCode(byte);
      continue;
    }

    body += `\\x${byte.toString(16).padStart(2, "0")}`;
  }

  return `b${quote}${body}${quote}`;
}

function selectQuote(raw) {
  const hasSingleQuote = raw.includes("'");
  const hasDoubleQuote = raw.includes('"');
  return hasSingleQuote && !hasDoubleQuote ? '"' : "'";
}

