import { basename } from "../path_utils.mjs";

const OPTION_A = { name: "--a", key: "a", metavar: "A" };
const OPTION_B = { name: "--b", key: "b", metavar: "B" };
const OPTION_ORDER = [OPTION_A, OPTION_B];
const KNOWN_TOKENS = new Set(["-h", "--help", OPTION_A.name, OPTION_B.name]);

export class CliParseExit extends Error {
  constructor(code, output) {
    super(output.trimEnd());
    this.name = "CliParseExit";
    this.code = code;
    this.output = output;
  }
}

export function parseTest6Arguments(processArgv) {
  const programName = basename(processArgv[1]) || "test6.mjs";
  const args = processArgv.slice(2);
  const parsed = new Map();
  const extras = [];

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (token === "-h" || token === "--help") {
      throw new CliParseExit(0, formatHelp(programName));
    }

    if (token === "--") {
      extras.push(...args.slice(index + 1));
      break;
    }

    const optionMatch = matchOption(token);
    if (!optionMatch) {
      extras.push(token);
      continue;
    }

    const rawValue = optionMatch.inlineValue ?? readNextValue(args, index, optionMatch.option, programName);
    if (optionMatch.inlineValue === undefined) {
      index += 1;
    }

    if (optionMatch.option.key === "a") {
      parsed.set("a", rawValue);
      continue;
    }

    const parsedInteger = parseIntegerValue(rawValue, programName);
    parsed.set("b", parsedInteger);
  }

  const missing = OPTION_ORDER.filter((option) => !parsed.has(option.key)).map((option) => option.name);
  if (missing.length > 0) {
    throw buildError(programName, `the following arguments are required: ${missing.join(", ")}`);
  }

  if (extras.length > 0) {
    throw buildError(programName, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return {
    a: parsed.get("a"),
    b: parsed.get("b"),
  };
}

function matchOption(token) {
  if (token === OPTION_A.name) {
    return { option: OPTION_A };
  }

  if (token === OPTION_B.name) {
    return { option: OPTION_B };
  }

  if (token.startsWith(`${OPTION_A.name}=`)) {
    return { option: OPTION_A, inlineValue: token.slice(OPTION_A.name.length + 1) };
  }

  if (token.startsWith(`${OPTION_B.name}=`)) {
    return { option: OPTION_B, inlineValue: token.slice(OPTION_B.name.length + 1) };
  }

  return null;
}

function readNextValue(args, index, option, programName) {
  const nextValue = args[index + 1];

  if (nextValue === undefined || nextValue === "--" || KNOWN_TOKENS.has(nextValue)) {
    throw buildError(programName, `argument ${option.name}: expected one argument`);
  }

  return nextValue;
}

function parseIntegerValue(rawValue, programName) {
  if (!/^[+-]?[0-9]+$/.test(rawValue)) {
    throw buildError(programName, `argument --b: invalid int value: '${rawValue}'`);
  }

  return BigInt(rawValue);
}

function buildError(programName, message) {
  return new CliParseExit(2, `${formatUsage(programName)}${programName}: error: ${message}\n`);
}

function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B\n`;
}

function formatHelp(programName) {
  return [
    `usage: ${programName} [-h] --a A --b B`,
    "",
    "options:",
    "  -h, --help  show this help message and exit",
    "  --a A",
    "  --b B",
    "",
  ].join("\n");
}

