export class PyBytes {
  constructor(raw) {
    this.raw = raw;
  }
}

export function createRawBytes(raw) {
  return new PyBytes(raw);
}

export function createAsciiBytes(text) {
  let position = 0;

  for (const character of text) {
    const codePoint = character.codePointAt(0);
    if (codePoint > 0x7f) {
      throw new AsciiEncodeError(position, codePoint);
    }
    position += 1;
  }

  return new PyBytes(text);
}

export function isPyBytes(value) {
  return value instanceof PyBytes;
}

export class AsciiEncodeError extends Error {
  constructor(position, codePoint) {
    super(
      `'ascii' codec can't encode character '${formatUnicodeEscape(codePoint)}' in position ${position}: ordinal not in range(128)`,
    );
    this.name = "UnicodeEncodeError";
    this.position = position;
    this.codePoint = codePoint;
  }
}

function formatUnicodeEscape(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${codePoint.toString(16).padStart(2, "0")}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${codePoint.toString(16).padStart(4, "0")}`;
  }

  return `\\U${codePoint.toString(16).padStart(8, "0")}`;
}
